(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.19)*12;
  const w1y = Math.cos(y*0.017-t*0.22)*16 + Math.sin(x*0.015+t*0.31)*11;
  const w2x = Math.sin((x+w1x)*0.012-t*0.15)*8 + Math.cos((y+w1y)*0.01+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.011+t*0.17)*7 + Math.sin((x+w1x)*0.014-t*0.13)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 80+Math.cos(t*0.38)*55, 0.075, 2.1, 0],
    [320+Math.cos(t*0.48)*105, 160+Math.sin(t*0.65)*55, 0.095, 1.75, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.4, 2.5],
    [100+Math.cos(t*0.75+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.55, 3.8],
    [370+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 5.0],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 1.95, 6.2],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+4)*50, 0.1, 2.2, 1.8],
    [420+Math.cos(t*0.42+2)*75, 200+Math.sin(t*0.58+1)*60, 0.07, 1.85, 4.5]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w = Math.sin(d*f - t*sp + ph);
    aS += w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + ph + 1.7);
    harm += Math.sin(d*f*1.41 + t*sp*0.3 + ph*0.5)*0.3;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, hm = harm/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.75) + Math.sin(sx*0.028-sy*0.038+t*1.05) + Math.sin(sx*0.015+sy*0.045-t*0.6))/3;
  const micro = (Math.sin(sx*0.08+sy*0.06+t*1.8)*Math.cos(sx*0.05-sy*0.09-t*1.3))*0.25;
