  const field = act - inh*0.65 + bg*0.35 + spiral + micro + moire*0.2 + hm*0.15;
  const reaction = Math.tanh(field*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t*0.9)*0.6 + Math.sin(sx*0.07-sy*0.11+t*0.4)*0.3)*1.3)*0.25;
  const pulse = 0.92 + Math.sin(t*0.4)*0.04 + Math.sin(t*1.1)*0.04;
  const blend = reaction*0.7 + cell*0.2 + moire*0.1;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5))*pulse;
  const pal = [[5,12,52],[10,45,85],[15,95,120],[25,150,135],[80,185,130],[190,195,70],[220,150,55],[210,90,60],[175,50,70],[100,25,60],[40,15,55],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + Math.abs(reaction)*0.18 : 1.0;
  const shimmer = Math.sin(reaction*8+t*3)*0.03 + 1.0;
  const lum = (0.82 + Math.sin(reaction*Math.PI)*0.18)*edge*shimmer;
